/**
 * Music bed + sound effects for «nuven-avatares», generated by code from
 * content/timing.json (← the real voice), so every footstep, pop and whoosh lands
 * on the frame where the picture reacts.
 *
 *   node scripts/music.mjs   →  assets/audio/music.wav + assets/audio/sfx.wav (48 kHz, 16-bit stereo)
 *
 * Original synthesis (no samples, no third-party music): free to use, see
 * content/creditos.md. Ducking under the voice is NOT baked in: the composition
 * carves the bed against the voice (HyperFrames voiceover carve).
 */
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const TM = JSON.parse(readFileSync(join(root, "content/timing.json"), "utf8"));
const DURATION = TM.duration;
const VOICE_END = TM.speech[1];
const S = Object.fromEntries(TM.scenes.map((s) => [s.id, s]));
const norm = (s) => s.toLowerCase().replace(/[^a-záéíóúñü ]/g, "");
const K = (txt, n = 0) => TM.keywords.filter((k) => norm(k.text) === norm(txt))[n].start;
const W = (txt, n = 0) => TM.words.filter((w) => norm(w.text) === norm(txt))[n].start;
const SR = 48000;
const N = Math.ceil(DURATION * SR);

// ───────────────────────── buffers & helpers ─────────────────────────
const bus = () => ({ L: new Float32Array(N), R: new Float32Array(N) });
const music = bus();
const sfx = bus();
// effect sends per stem, so each stem carries its own reverb (mixable separately in Studio)
const sends = new Map([
  [music, { verb: bus(), delay: bus() }],
  [sfx, { verb: bus(), delay: bus() }],
]);
const duck = new Float32Array(N).fill(1); // sidechain gain written by the kick

const clamp = (v, a = 0, b = 1) => Math.min(b, Math.max(a, v));
const lerp = (a, b, t) => a + (b - a) * t;
const smooth = (t) => {
  const x = clamp(t);
  return x * x * (3 - 2 * x);
};
const ramp = (t, a, b) => smooth((t - a) / (b - a));
const mtof = (m) => 440 * 2 ** ((m - 69) / 12);
const idx = (t) => Math.max(0, Math.min(N, Math.round(t * SR)));

let seed = 12345;
const rnd = () => {
  seed = (seed + 0x6d2b79f5) >>> 0;
  let r = Math.imul(seed ^ (seed >>> 15), 1 | seed);
  r = (r + Math.imul(r ^ (r >>> 7), 61 | r)) ^ r;
  return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
};
const noise = () => rnd() * 2 - 1;

/** Equal-power pan, p in [-1, 1]. */
const panGains = (p) => [Math.cos(((p + 1) * Math.PI) / 4), Math.sin(((p + 1) * Math.PI) / 4)];

/** Topology-preserving state-variable filter (Zavalishin). */
class SVF {
  ic1 = 0;
  ic2 = 0;
  run(x, fc, q = 0.707) {
    const g = Math.tan((Math.PI * Math.min(fc, SR * 0.45)) / SR);
    const k = 1 / q;
    const a1 = 1 / (1 + g * (g + k));
    const a2 = g * a1;
    const a3 = g * a2;
    const v3 = x - this.ic2;
    const v1 = a1 * this.ic1 + a2 * v3;
    const v2 = this.ic2 + a2 * this.ic1 + a3 * v3;
    this.ic1 = 2 * v1 - this.ic1;
    this.ic2 = 2 * v2 - this.ic2;
    return { lp: v2, bp: v1, hp: x - k * v1 - v2 };
  }
}

/**
 * Renders a voice from t0 for dur seconds. fn(tl, i) returns a sample (mono)
 * or [l, r]; pan may be a number or a function of tl. send = reverb amount.
 */
function voice(target, t0, dur, fn, { pan = 0, gain = 1, verb = 0, delay = 0, ducked = false } = {}) {
  const a = idx(t0);
  const b = idx(t0 + dur);
  for (let i = a; i < b; i++) {
    const tl = (i - a) / SR;
    let v = fn(tl, i);
    let l, r;
    if (Array.isArray(v)) [l, r] = v;
    else {
      const [gl, gr] = panGains(typeof pan === "function" ? pan(tl) : pan);
      l = v * gl;
      r = v * gr;
    }
    const g = gain * (ducked ? duck[i] : 1);
    l *= g;
    r *= g;
    target.L[i] += l;
    target.R[i] += r;
    const fx = sends.get(target);
    if (verb) {
      fx.verb.L[i] += l * verb;
      fx.verb.R[i] += r * verb;
    }
    if (delay) {
      fx.delay.L[i] += l * delay;
      fx.delay.R[i] += r * delay;
    }
  }
}

/** Band-limited-ish saw (polyBLEP). */
function sawOsc() {
  let ph = rnd();
  return (f) => {
    const dt = f / SR;
    ph += dt;
    if (ph >= 1) ph -= 1;
    let v = 2 * ph - 1;
    if (ph < dt) {
      const t = ph / dt;
      v -= t + t - t * t - 1;
    } else if (ph > 1 - dt) {
      const t = (ph - 1) / dt;
      v -= t * t + t + t + 1;
    }
    return v;
  };
}


// ───────────────────────── score ─────────────────────────
// Minimal, warm and a little melancholic on the street (D minor, 92 BPM, FM piano,
// sub and a soft pad), a held breath under «La razón es sencilla», tension inside the
// phone, a lift to D major when the web arrives, silence under «¿Y quién me la hace?»
// and the full groove from «Nuven Digital». The tail after the voice is silent.
const BEAT = 60 / 92;
const BAR = BEAT * 4;
const MINOR = [
  { bass: 26, keys: [53, 57, 60, 64] }, // Dm9 (F A C E)
  { bass: 22, keys: [50, 53, 57, 62] }, // Bbmaj7
  { bass: 31, keys: [53, 57, 58, 62] }, // Gm9
  { bass: 33, keys: [52, 55, 57, 61] }, // A7sus → A
];
const MAJOR = [
  { bass: 26, keys: [54, 57, 62, 64] }, // Dadd9
  { bass: 33, keys: [52, 57, 61, 64] }, // A/C#
  { bass: 35, keys: [54, 57, 59, 62] }, // Bm7
  { bass: 31, keys: [54, 59, 62, 66] }, // Gmaj7
];
const LOGO = K("nuven digital");
const BREATH = [K("sencilla") - 0.75, W("el", 2) - 0.32]; // near-silence before the phone lands
const QUIET = [S.marca.start + 0.1, LOGO - 0.02]; // silence under the question, the brand hits after it
const LIFT = S.web.start;
const END = Math.min(DURATION, VOICE_END + 1.1); // music is gone before the silent tail
const RESOLVE = K("escríbenos") - 0.2;
const inR = (t, [a, b]) => t >= a && t < b;
const chordAt = (t) => (t >= RESOLVE ? { bass: 26, keys: [54, 57, 61, 64, 69] } : (t >= LIFT ? MAJOR : MINOR)[Math.floor(t / BAR) % 4]);
const beats = (a, b, div = 1) => {
  const out = [];
  const step = BEAT / div;
  for (let n = Math.ceil(a / step - 1e-6); n * step < b - 1e-6; n++) out.push([n * step, n]);
  return out;
};
function energy(t) {
  if (t < S.busqueda.start) return 0.45;
  if (t < LIFT) return 0.55;
  if (t < S.marca.start) return 0.72;
  return 0.85;
}
const bedEnv = (t) => ramp(t, 0, 1.0) * (1 - 0.94 * smooth((t - BREATH[0]) / 0.35) * (1 - smooth((t - BREATH[1]) / 0.05))) * (inR(t, QUIET) ? 0 : 1) * (1 - ramp(t, END - 1.4, END));

function kick(t0, amp = 1) {
  voice(music, t0, 0.42, (tl) => {
    const f = 48 + 100 * Math.exp(-tl * 40);
    return Math.tanh(1.4 * Math.sin(2 * Math.PI * f * tl * (1 + 0.6 * Math.exp(-tl * 40)))) * Math.exp(-tl * 9) * amp * bedEnv(t0 + tl);
  }, { gain: 0.5 });
  const a = idx(t0);
  for (let i = a; i < Math.min(N, a + idx(BEAT * 0.9)); i++) duck[i] = Math.min(duck[i], 1 - 0.45 * Math.exp(-((i - a) / SR) * 7));
}
function shaker(t0, amp = 1, pan = 0.3) {
  const f = new SVF();
  voice(music, t0, 0.06, (tl) => f.run(noise(), 7000, 1.4).bp * Math.min(1, tl / 0.004) * Math.exp(-tl * 60) * amp * bedEnv(t0 + tl), { gain: 0.08, pan });
}
function clap(t0, amp = 1) {
  const f = new SVF();
  voice(music, t0, 0.3, (tl) => {
    const env = tl < 0.025 ? Math.exp(-((tl % 0.008) * 450)) : Math.exp(-(tl - 0.02) * 18);
    return f.run(noise(), 1500, 1.1).bp * env * amp * bedEnv(t0 + tl);
  }, { gain: 0.2, verb: 0.3 });
}
function bassNote(t0, dur, midi, amp = 1) {
  const f = new SVF();
  const osc = sawOsc();
  voice(music, t0, dur, (tl) => {
    const fr = mtof(midi);
    const env = Math.min(1, tl / 0.008) * Math.exp(-tl * 3.5) * (tl > dur - 0.03 ? Math.max(0, (dur - tl) / 0.03) : 1);
    const body = Math.sin(2 * Math.PI * fr * tl) * 0.9 + f.run(osc(fr), 300 + 700 * Math.exp(-tl * 14), 1.0).lp * 0.35;
    return Math.tanh(1.2 * body) * env * amp * energy(t0) * bedEnv(t0 + tl);
  }, { gain: 0.32, ducked: true });
}
function epiano(t0, midi, dur, amp = 1, pan = 0) {
  const fc = mtof(midi);
  voice(music, t0, dur + 0.5, (tl) => {
    const env = Math.min(1, tl / 0.005) * Math.exp(-tl * 1.5) * (tl > dur ? Math.exp(-(tl - dur) * 8) : 1);
    const ix = 1.3 * Math.exp(-tl * 5) + 0.2;
    const tine = Math.sin(2 * Math.PI * fc * tl + ix * Math.sin(2 * Math.PI * fc * tl));
    return tine * env * amp * bedEnv(t0 + tl);
  }, { gain: 0.05, pan, verb: 0.35, delay: 0.12, ducked: true });
}
function pluck(t0, midi, pan, amp = 1) {
  const f = new SVF();
  const osc = sawOsc();
  voice(music, t0, 0.45, (tl) => {
    const env = Math.min(1, tl / 0.003) * Math.exp(-tl * 9);
    return f.run(osc(mtof(midi)), 900 + 3200 * Math.exp(-tl * 14), 1).lp * env * amp * bedEnv(t0 + tl);
  }, { gain: 0.05, pan, verb: 0.25, delay: 0.25, ducked: true });
}
function bell(target, t0, midi, { dur = 2, amp = 1, pan = 0, verb = 0.45, bright = 1, gain = 0.12 } = {}) {
  const fc = mtof(midi);
  voice(target, t0, dur, (tl) => {
    const env = Math.min(1, tl / 0.003) * Math.exp(-tl * (4.8 / dur));
    return Math.sin(2 * Math.PI * fc * tl + bright * 2 * Math.exp(-tl * 4) * Math.sin(2 * Math.PI * fc * 3.5 * tl)) * env * amp;
  }, { gain, pan, verb });
}

// drums: shaker on the street, kick from the lift, claps from the brand on
for (const [b, n] of beats(LIFT, END)) {
  kick(b, b >= LOGO ? 1 : 0.75);
  if (b >= LOGO && n % 2 === 1) clap(b, 0.9);
}
for (const [t, n] of beats(0, END, 2)) {
  if (t >= S.busqueda.start && t < LIFT) continue;
  shaker(t, (n % 2 ? 1 : 0.5) * (t < LIFT ? 0.6 : 1), n % 2 ? 0.3 : -0.15);
}
// bass: whole notes on the street, pulsing eighths inside the phone, off-beats after the lift
for (const [b, n] of beats(0, END)) {
  const ch = chordAt(b);
  if (b < S.busqueda.start) { if (n % 4 === 0) bassNote(b, BAR * 0.95, ch.bass + 12, 0.8); }
  else if (b < LIFT) { bassNote(b, BEAT * 0.45, ch.bass + 12, 0.7); bassNote(b + BEAT / 2, BEAT * 0.45, ch.bass + 12, 0.5); }
  else bassNote(b + BEAT / 2, BEAT * 0.45, ch.bass + 12, 0.9);
}
// FM piano: held chords before the lift, syncopated stabs after
for (let bar = 0; bar * BAR < END; bar++) {
  const t = bar * BAR;
  const ch = chordAt(t);
  if (t < LIFT) { ch.keys.forEach((m, k) => epiano(t + k * 0.03, m, BAR * 0.95, 0.75, (k - 1.5) * 0.2)); continue; }
  for (const [off, len] of [[0, 1.4], [1.5, 1.2], [3, 0.9]]) ch.keys.forEach((m, k) => epiano(t + off * BEAT + k * 0.008, m, len * BEAT, 0.85, (k - 1.5) * 0.2));
}
// arpeggio: inside the phone (sparse, tense) and over the web/brand (busy)
for (const [t, n] of beats(W("el", 2) - 0.3, END, 4)) {
  if (t < LIFT && n % 2) continue;
  const keys = chordAt(t).keys;
  pluck(t, keys[[0, 2, 1, 3, 2, 1, 3, 2][n % 8] % keys.length] + 12, n % 2 ? 0.35 : -0.35, t >= LIFT ? 0.8 : 0.5);
}
// soft pad underneath everything
{
  const vs = [0, 1, 2, 3, 4].map(() => [sawOsc(), sawOsc()]);
  const fl = [new SVF(), new SVF()];
  let cut = 700;
  voice(music, 0, END, (t) => {
    const env = bedEnv(t);
    if (env <= 0.0001) return [0, 0];
    const notes = chordAt(t).keys;
    cut += (600 + 2200 * energy(t) - cut) * 0.0004;
    let l = 0;
    let r = 0;
    notes.forEach((m, n) => {
      l += vs[n][0](mtof(m) * 0.997);
      r += vs[n][1](mtof(m) * 1.003);
    });
    return [fl[0].run(l, cut, 0.7).lp * env, fl[1].run(r, cut * 1.03, 0.7).lp * env];
  }, { gain: 0.03, verb: 0.35, ducked: true });
}
bell(music, RESOLVE + 0.02, 81, { dur: 2.6, amp: 0.35, verb: 0.6, gain: 0.07 });

// ───────────────────────── sound effects (subtle) ─────────────────────────
function whoosh(t0, dur, { from = -0.6, to = 0.6, lo = 300, hi = 4500, amp = 1, q = 1.2 } = {}) {
  const f = new SVF();
  voice(sfx, t0, dur, (tl) => {
    const x = tl / dur;
    return f.run(noise(), lo * (hi / lo) ** smooth(x), q).bp * Math.sin(Math.PI * Math.min(1, x)) ** 1.8 * amp;
  }, { gain: 0.3, pan: (tl) => lerp(from, to, smooth(tl / dur)), verb: 0.15 });
}
function tick(t0, { f = 2800, amp = 1, pan = 0 } = {}) {
  voice(sfx, t0, 0.03, (tl) => (Math.sin(2 * Math.PI * f * tl) * 0.75 + noise() * 0.25) * Math.exp(-tl * 190) * amp, { gain: 0.14, pan, verb: 0.03 });
}
function pop(t0, midi, pan = 0, amp = 0.8) {
  bell(sfx, t0, midi, { dur: 0.6, amp, pan, verb: 0.2, bright: 0.5, gain: 0.1 });
  tick(t0, { f: 1800, amp: 0.6, pan });
}
function thump(t0, amp = 1) {
  voice(sfx, t0, 1.0, (tl) => Math.tanh(1.4 * Math.sin(2 * Math.PI * (46 + 40 * Math.exp(-tl * 20)) * tl)) * Math.exp(-tl * 4) * amp, { gain: 0.35, verb: 0.3 });
}
function step(t0, amp = 1, pan = 0) {
  const f = new SVF();
  voice(sfx, t0, 0.09, (tl) => f.run(noise(), 420, 0.9).lp * Math.min(1, tl / 0.003) * Math.exp(-tl * 45) * amp, { gain: 0.5, pan, verb: 0.05 });
}
function key(t0, pan = 0.2) {
  const f = new SVF();
  voice(sfx, t0, 0.04, (tl) => f.run(noise(), 3200, 2).bp * Math.exp(-tl * 120), { gain: 0.16, pan });
}
function swipe(t0, dur = 0.28, amp = 0.7) { whoosh(t0, dur, { lo: 1200, hi: 6000, amp, q: 1.6, from: 0.2, to: -0.2 }); }
function chime(t0, notes, amp = 0.5) { notes.forEach((m, k) => bell(sfx, t0 + k * 0.07, m, { dur: 1.2, amp, verb: 0.4, gain: 0.08, pan: (k - 1) * 0.2 })); }
function walkSteps(t0, dur, stepLen = 0.26, amp = 0.6, pan = 0) { for (let t = t0; t < t0 + dur; t += stepLen) step(t, amp * (0.8 + 0.2 * rnd()), pan); }
function bonk(t0) { voice(sfx, t0, 0.35, (tl) => Math.sin(2 * Math.PI * (220 - 90 * tl) * tl) * Math.exp(-tl * 12), { gain: 0.12, verb: 0.2 }); }
function ring(t0, n = 3) { for (let k = 0; k < n; k++) voice(sfx, t0 + k * 0.14, 0.1, (tl) => (Math.sin(2 * Math.PI * 1320 * tl) + Math.sin(2 * Math.PI * 1650 * tl)) * 0.5 * Math.exp(-tl * 18), { gain: 0.07, pan: 0.2 }); }
function rise(t0, dur, amp = 1) { voice(sfx, t0, dur, (tl) => Math.sin(2 * Math.PI * (300 + 600 * (tl / dur) ** 1.6) * tl) * Math.sin(Math.PI * tl / dur) * amp, { gain: 0.035, verb: 0.4 }); }
// street ambience: distant hum and air, under the street scenes only
{
  const f = new SVF(), g = new SVF();
  const streetOn = (t) => (t < S.busqueda.start ? 1 : 0) + (t >= S.informatica.start && t < S.web.start ? 0.6 : 0) + (t >= S.marca.start && t < LOGO ? 0.6 : 0) + (t >= S.cierre.start && t < END ? 1 : 0);
  let lvl = 0;
  voice(sfx, 0, END, (t) => {
    lvl += (streetOn(t) - lvl) * 0.0006;
    return [f.run(noise(), 500, 0.6).lp * 0.6 * lvl, g.run(noise(), 520, 0.6).lp * 0.6 * lvl];
  }, { gain: 0.05 });
}
// 1 · the client leaves (door bell, footsteps)
const cl = K("clientes");
bell(sfx, cl - 0.5, 88, { dur: 0.9, amp: 0.5, verb: 0.3, gain: 0.07, pan: -0.3 });
bell(sfx, cl - 0.42, 84, { dur: 0.9, amp: 0.4, verb: 0.3, gain: 0.07, pan: -0.3 });
walkSteps(cl - 0.3, 2.3, 0.26, 0.55, 0.1);
pop(W("abrió") + 0.35, 76, 0.4, 0.5);
pop(cl - 0.4, 74, 0, 0.5);
pop(W("yo"), 72, -0.4, 0.5);
// 2 · shrug, prices, walking away together
pop(K("entiendo") + 0.1, 79, -0.2, 0.5);
pop(W("precios"), 72, -0.4);
pop(K("los mismos") - 0.05, 72, 0.4);
pop(K("los mismos") + 0.25, 79, 0);
walkSteps(K("con el otro") - 0.15, 1.3, 0.26, 0.6, 0.5);
// transitions (the N ribbon)
for (const t of [S.busqueda.start + 0.05, S.web.start + 0.1, LOGO - 0.05, S.cierre.start + 0.1]) whoosh(t - 0.3, 0.6, { amp: 0.8 });
// 3 · the phone lands, typing, pins, results, the missing pin
const ph = W("el", 2) - 0.3;
whoosh(ph, 0.5, { lo: 200, hi: 3000, from: 0.5, to: 0, amp: 0.7 });
thump(ph + 0.45, 0.55);
const t0 = W("el", 2) + 0.55;
for (let i = 0; i < "negocios cerca de mí".length; i++) key(t0 + i * 0.055, 0.15 + (i % 3) * 0.05);
[0, 1, 2].forEach((i) => tick(K("móvil") - 0.55 + i * 0.12, { f: 2400 + i * 300, amp: 0.7 }));
swipe(K("móvil"));
bonk(K("no te ha encontrado") + 0.1);
// 4 · the rival's listing
swipe(K("sí") - 0.05);
[0, 1, 2].forEach((i) => pop(K("fotos") - 0.1 + i * 0.1, 76 + i * 3, 0.2));
for (let i = 0; i < 5; i++) tick(K("reseñas") + i * 0.1, { f: 3000 + i * 200, amp: 0.5 });
pop(K("botón para reservar"), 81, 0.1);
tick(K("botón para reservar") + 0.5, { f: 1500, amp: 1 });
// 5 · the laptop and the question marks
whoosh(S.informatica.start - 0.15, 0.45, { from: 0, to: 0.4, lo: 300, hi: 2000, amp: 0.5 });
pop(W("pero") + 0.15, 69, 0.4, 0.5);
pop(K("informática"), 76, -0.3, 0.5);
pop(K("informática") + 0.25, 79, 0.2, 0.5);
// 6 · the web builds piece by piece, then folds into the phone
whoosh(K("no hace falta") + 0.2, 0.5, { lo: 400, hi: 3000, amp: 0.5 });
[["web", 72], ["trabajo", 76], ["opiniones", 79], ["teléfono", 84]].forEach(([w, m]) => pop(K(w), m, 0.2));
swipe(K("te vean") - 0.35, 0.4);
chime(K("te vean") + 0.3, [74, 78, 81]);
// 7 · silence, then the brand: ribbon, thump, bell, the ring fills
thump(LOGO + 0.05, 0.9);
bell(sfx, LOGO + 0.05, 74, { dur: 2.2, amp: 0.6, verb: 0.55, gain: 0.1 });
rise(LOGO + 1.5, 1.3);
bell(sfx, LOGO + 2.8, 86, { dur: 1.2, amp: 0.4, verb: 0.5, gain: 0.07 });
// 8 · icons
pop(K("a medida") - 0.15, 74, -0.3);
pop(K("rápidas") - 0.15, 78, 0);
pop(K("te encuentren") - 0.15, 81, 0.3);
ring(K("te llamen") + 0.05);
// 9 · the end card
pop(K("veinte años", 2) + 0.15, 74, -0.2);
chime(K("ser vistos"), [74, 78, 81, 86], 0.4);
pop(K("escríbenos") - 0.15, 79, 0.1);
tick(K("escríbenos") + 1.0, { f: 1500, amp: 1, pan: 0.3 });
pop(K("escríbenos") + 1.1, 86, 0.3, 0.5);
pop(K("proyecto"), 81, 0, 0.5);

// ───────────────────────── effects buses & master ─────────────────────────
/** Ping-pong delay: left line fed by the input, right line by the left (dotted eighth). */
function pingPong(src, dst, time = BEAT * 0.75, fb = 0.38) {
  const d = Math.round(time * SR);
  const L = new Float32Array(N);
  const R = new Float32Array(N);
  for (let i = 0; i < N; i++) {
    const dl = i >= d ? L[i - d] : 0;
    const dr = i >= d ? R[i - d] : 0;
    L[i] = (src.L[i] + src.R[i]) * 0.5 + dr * fb;
    R[i] = dl;
    dst.L[i] += dl * 0.5;
    dst.R[i] += dr * 0.5;
  }
}
function freeverb(src) {
  const s = SR / 44100;
  const combs = [1116, 1188, 1277, 1356, 1422, 1491, 1557, 1617];
  const aps = [556, 441, 341, 225];
  const out = bus();
  for (const [ch, spread] of [
    ["L", 0],
    ["R", 23],
  ]) {
    const x = src[ch];
    const y = out[ch];
    for (const c of combs) {
      const len = Math.round((c + spread) * s);
      const buf = new Float32Array(len);
      let p = 0;
      let store = 0;
      for (let i = 0; i < N; i++) {
        const o = buf[p];
        store = o * 0.75 + store * 0.25; // damping
        buf[p] = x[i] * 0.015 + store * 0.86; // room size
        y[i] += o;
        if (++p >= len) p = 0;
      }
    }
    for (const a of aps) {
      const len = Math.round((a + spread) * s);
      const buf = new Float32Array(len);
      let p = 0;
      for (let i = 0; i < N; i++) {
        const b = buf[p];
        const inp = y[i];
        y[i] = b - inp;
        buf[p] = inp + b * 0.5;
        if (++p >= len) p = 0;
      }
    }
  }
  return out;
}


for (const [stem, fx] of sends) {
  pingPong(fx.delay, stem);
  pingPong(fx.delay, fx.verb);
  const wet = freeverb(fx.verb);
  for (let i = 0; i < N; i++) {
    stem.L[i] += wet.L[i] * 0.9;
    stem.R[i] += wet.R[i] * 0.9;
  }
}
// hard edges: silence at both ends
for (const b of [music, sfx]) {
  const a = idx(0.02);
  const z = idx(DURATION - 0.05);
  for (let i = 0; i < N; i++) {
    const g = i < a ? i / a : i >= z ? Math.max(0, 1 - (i - z) / (N - z)) : 1;
    b.L[i] *= g;
    b.R[i] *= g;
  }
}
// each stem peak-normalised to -6 dBFS; levels are set in the mix (data-volume)
function normalise(b, db = -6) {
  let p = 0;
  for (let i = 0; i < N; i++) p = Math.max(p, Math.abs(b.L[i]), Math.abs(b.R[i]));
  const g = 10 ** (db / 20) / (p || 1);
  for (let i = 0; i < N; i++) {
    b.L[i] *= g;
    b.R[i] *= g;
  }
}
normalise(music);
normalise(sfx);
const soft = (v) => v;
function wav(path, b) {
  const data = Buffer.alloc(N * 4);
  for (let i = 0; i < N; i++) {
    data.writeInt16LE(Math.round(clamp(soft(b.L[i]), -1, 1) * 32767), i * 4);
    data.writeInt16LE(Math.round(clamp(soft(b.R[i]), -1, 1) * 32767), i * 4 + 2);
  }
  const h = Buffer.alloc(44);
  h.write("RIFF", 0);
  h.writeUInt32LE(36 + data.length, 4);
  h.write("WAVE", 8);
  h.write("fmt ", 12);
  h.writeUInt32LE(16, 16);
  h.writeUInt16LE(1, 20);
  h.writeUInt16LE(2, 22);
  h.writeUInt32LE(SR, 24);
  h.writeUInt32LE(SR * 4, 28);
  h.writeUInt16LE(4, 32);
  h.writeUInt16LE(16, 34);
  h.write("data", 36);
  h.writeUInt32LE(data.length, 40);
  writeFileSync(path, Buffer.concat([h, data]));
}


const dir = join(root, "assets/audio");
mkdirSync(dir, { recursive: true });
wav(join(dir, "music.wav"), music);
wav(join(dir, "sfx.wav"), sfx);
console.log(`✓ assets/audio/music.wav + sfx.wav · ${DURATION.toFixed(2)}s`);
